// Copia del HTML de cada página. El inspector la usa si no puede leer los archivos publicados
// (por ejemplo, al abrir el sitio con doble clic en lugar de un servidor).
window.PAGINAS_HTML = {"index.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Inicio · Graficación</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&family=Literata:ital,wght@0,400;0,600;1,400&display=swap\" />\n  <link rel=\"stylesheet\" href=\"css/styles.css\" />\n  \n</head>\n<body>\n  <header class=\"barra\">\n    <div class=\"barra-interior\">\n      <a class=\"marca\" href=\"index.html\">Graficación</a>\n      <button class=\"boton-menu\" id=\"boton-menu\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n      <nav class=\"menu\" id=\"menu\" aria-label=\"Principal\">\n        <a href=\"index.html\" aria-current=\"page\">Inicio</a>\n        <a href=\"canvas.html\">El canvas</a>\n        <a href=\"p5.html\">p5.js</a>\n        <a href=\"dom.html\">El DOM</a>\n        <a href=\"dom-inspector.html\">Inspector DOM</a>\n        <span class=\"grupo\">Proyectos</span>\n        <a href=\"proyectos/rana.html\">Rana</a>\n        <a href=\"proyectos/dientes.html\">Dientes de conejo</a>\n        <a href=\"proyectos/cena.html\">¿Qué hay de cena?</a>\n        <a href=\"proyectos/nevado.html\">Día nevado soleado</a>\n        <a href=\"proyectos/muneco.html\">Muñeco de nieve</a>\n      </nav>\n    </div>\n  </header>\n  <main>\n    <section class=\"hero\">\n      <div>\n        <h1>Dibujar con código</h1>\n        <p class=\"intro\">Este sitio reúne los cinco dibujos que hice en Khan Academy, ahora escritos con p5.js y\n        publicados como una página web real. El día nevado ahora tiene nieve que cae y el muñeco de nieve tiene sombrero, nariz y ojos.</p>\n        <p class=\"intro\">Abajo están los proyectos. Si quieres entender cómo funcionan por dentro, lee antes\n        <a href=\"canvas.html\">la página del canvas</a>, <a href=\"p5.html\">la de p5.js</a> y <a href=\"dom.html\">la del DOM</a>. Para ver cómo está armada cada página por dentro, usa el <a href=\"dom-inspector.html\">inspector del DOM</a>.</p>\n      </div>\n      <div>\n        <div class=\"lienzo-caja\"><canvas id=\"plano\" width=\"560\" height=\"340\" aria-label=\"Plano cartesiano que muestra las coordenadas del puntero\"></canvas></div>\n        <p class=\"pie-lienzo\">Mueve el mouse sobre el plano. El origen (0, 0) está arriba a la izquierda y la y crece hacia abajo.</p>\n      </div>\n    </section>\n\n    <section>\n    <h2>Proyectos</h2>\n    <ul class=\"lista-proyectos\">\n      <li><a href=\"proyectos/rana.html\"><span class=\"nombre\">Rana</span><span class=\"desc\">Una rana verde con ojos saltones, hecha solo con círculos y cuadrados.</span></a></li>\n      <li><a href=\"proyectos/dientes.html\"><span class=\"nombre\">Dientes de conejo</span><span class=\"desc\">Un conejo con orejas rosas, mejillas, bigotes y dos dientes grandes.</span></a></li>\n      <li><a href=\"proyectos/cena.html\"><span class=\"nombre\">¿Qué hay de cena?</span><span class=\"desc\">Un plato servido en una mesa de madera: bistec, puré de papa, brócoli, zanahorias y cubiertos.</span></a></li>\n      <li><a href=\"proyectos/nevado.html\"><span class=\"nombre\">Día nevado soleado</span><span class=\"desc\">Un muñeco de nieve bajo el sol, con nieve que cae sin parar.</span></a></li>\n      <li><a href=\"proyectos/muneco.html\"><span class=\"nombre\">Muñeco de nieve</span><span class=\"desc\">Un muñeco con sombrero, bufanda, nariz de zanahoria, ojos y boca de carbón.</span></a></li>\n    </ul>\n    </section>\n\n    <section>\n    <h2>Qué contiene este sitio</h2>\n    <p>La sección teórica explica la etiqueta <code>&lt;canvas&gt;</code> con su contexto de renderizado 2D, los\n    fundamentos de p5.js, que es la librería con la que se hicieron los dibujos, y el DOM, que es como JavaScript modifica la página. Cada proyecto tiene su propia\n    página con una descripción, los conceptos que aplica y un botón para ver su código fuente.</p>\n    </section>\n\n\n  </main>\n  <footer>\n    <!-- Aquí va el nombre del alumno -->\n    Práctica de Graficación · Hecho con HTML, CSS, JavaScript y p5.js · Espinosa Perez Jose Hugo\n  </footer>\n  <script src=\"js/main.js\"></script>\n  \n</body>\n</html>\n", "canvas.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>El canvas · Graficación</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&family=Literata:ital,wght@0,400;0,600;1,400&display=swap\" />\n  <link rel=\"stylesheet\" href=\"css/styles.css\" />\n  \n</head>\n<body>\n  <header class=\"barra\">\n    <div class=\"barra-interior\">\n      <a class=\"marca\" href=\"index.html\">Graficación</a>\n      <button class=\"boton-menu\" id=\"boton-menu\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n      <nav class=\"menu\" id=\"menu\" aria-label=\"Principal\">\n        <a href=\"index.html\">Inicio</a>\n        <a href=\"canvas.html\" aria-current=\"page\">El canvas</a>\n        <a href=\"p5.html\">p5.js</a>\n        <a href=\"dom.html\">El DOM</a>\n        <a href=\"dom-inspector.html\">Inspector DOM</a>\n        <span class=\"grupo\">Proyectos</span>\n        <a href=\"proyectos/rana.html\">Rana</a>\n        <a href=\"proyectos/dientes.html\">Dientes de conejo</a>\n        <a href=\"proyectos/cena.html\">¿Qué hay de cena?</a>\n        <a href=\"proyectos/nevado.html\">Día nevado soleado</a>\n        <a href=\"proyectos/muneco.html\">Muñeco de nieve</a>\n      </nav>\n    </div>\n  </header>\n  <main>\n    <h1>La etiqueta &lt;canvas&gt; y el contexto 2D</h1>\n    <p class=\"intro\">El <code>&lt;canvas&gt;</code> es el lienzo de la web: un rectángulo de píxeles en el que dibujas con JavaScript.\n    p5.js, y los dibujos de este sitio, están construidos encima de él.</p>\n\n    <section>\n    <h2>Qué es</h2>\n    <p><code>&lt;canvas&gt;</code> es un elemento de HTML5 que reserva un área rectangular de la página. Por sí solo no muestra nada:\n    es una superficie en blanco y transparente. Todo lo que aparece en ella se dibuja con código JavaScript.</p>\n    <p>Es un lienzo de <strong>mapa de bits</strong> (raster): guarda una cuadrícula de píxeles, no una lista de objetos.\n    Si dibujas un círculo y después quieres moverlo, no puedes \"agarrarlo\": tienes que borrar la zona y dibujarlo de nuevo.\n    Por eso las animaciones se hacen redibujando todo en cada cuadro.</p>\n    <p>El texto que pongas entre las etiquetas de apertura y cierre solo se muestra en navegadores que no soportan canvas.</p>\n\n    <h3>Tamaño del canvas</h3>\n    <p>El tamaño se define con los atributos <code>width</code> y <code>height</code>. Si no los pones, el canvas mide 300 × 150 píxeles.\n    Cambiar el tamaño solo con CSS no cambia la cantidad de píxeles: estira o encoge la imagen y el dibujo se ve borroso o deformado.\n    Por eso en la práctica de clase se asignó <code>canvas.width = 500</code> desde JavaScript.</p>\n    </section>\n\n    <section>\n    <h2>Cómo se usa: tres pasos</h2>\n<pre><code>&lt;canvas id=\"lienzo\" width=\"400\" height=\"300\"&gt;\n  Tu navegador no soporta canvas.\n&lt;/canvas&gt;\n\n&lt;script&gt;\n  // 1. Obtener el elemento\n  const lienzo = document.getElementById('lienzo');\n  // 2. Pedir el contexto de renderizado\n  const ctx = lienzo.getContext('2d');\n  // 3. Dibujar\n  ctx.fillStyle = '#27c1e0';\n  ctx.fillRect(20, 20, 150, 100);\n&lt;/script&gt;</code></pre>\n    </section>\n\n    <section>\n    <h2>Contextos de renderizado</h2>\n    <p>Un contexto de renderizado es el objeto que trae las herramientas para dibujar. Se obtiene con\n    <code>canvas.getContext(tipo)</code>, y el <em>tipo</em> decide cómo se dibuja.</p>\n    <div class=\"tabla-envoltura\">\n      <table>\n        <thead><tr><th>Tipo</th><th>Para qué sirve</th></tr></thead>\n        <tbody>\n          <tr><td><code>'2d'</code></td><td>Gráficos en dos dimensiones: formas, líneas, texto, imágenes. Devuelve un <code>CanvasRenderingContext2D</code>. Es el que usamos aquí.</td></tr>\n          <tr><td><code>'webgl'</code> y <code>'webgl2'</code></td><td>Gráficos 3D acelerados por la tarjeta gráfica (GPU). Son más potentes y más complejos. p5.js los usa en su modo <code>WEBGL</code>.</td></tr>\n          <tr><td><code>'bitmaprenderer'</code></td><td>Muestra de forma eficiente una imagen ya creada (<code>ImageBitmap</code>) sin dibujar sobre ella.</td></tr>\n          <tr><td><code>'webgpu'</code></td><td>La interfaz más moderna para usar la GPU. Su soporte todavía depende del navegador.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"nota\"><p>Un canvas solo puede tener un tipo de contexto. Si ya pediste <code>'2d'</code> y luego pides <code>'webgl'</code>\n    sobre el mismo canvas, el navegador devuelve <code>null</code>.</p></div>\n    </section>\n\n    <section>\n    <h2>Sistema de coordenadas</h2>\n    <p>El origen <code>(0, 0)</code> está en la <strong>esquina superior izquierda</strong>. La <code>x</code> crece hacia la derecha\n    y la <code>y</code> crece hacia <strong>abajo</strong>, al revés de la gráfica de matemáticas. Puedes comprobarlo en el plano\n    de la <a href=\"index.html\">página de inicio</a>.</p>\n    </section>\n\n    <section>\n    <h2>El contexto 2D: lo que más se usa</h2>\n    <div class=\"tabla-envoltura\">\n      <table>\n        <thead><tr><th>Tema</th><th>Métodos y propiedades</th></tr></thead>\n        <tbody>\n          <tr><td>Rectángulos</td><td><code>fillRect(x, y, ancho, alto)</code>, <code>strokeRect()</code>, <code>clearRect()</code></td></tr>\n          <tr><td>Trazados</td><td><code>beginPath()</code>, <code>moveTo()</code>, <code>lineTo()</code>, <code>arc(x, y, radio, inicio, fin)</code>, <code>closePath()</code>, luego <code>fill()</code> o <code>stroke()</code></td></tr>\n          <tr><td>Estilos</td><td><code>fillStyle</code>, <code>strokeStyle</code>, <code>lineWidth</code>, <code>globalAlpha</code></td></tr>\n          <tr><td>Texto</td><td><code>font</code>, <code>fillText(texto, x, y)</code>, <code>measureText()</code></td></tr>\n          <tr><td>Transformaciones</td><td><code>translate()</code>, <code>rotate()</code>, <code>scale()</code>, <code>save()</code> y <code>restore()</code></td></tr>\n          <tr><td>Imágenes</td><td><code>drawImage(imagen, x, y)</code></td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p>Los ángulos de <code>arc()</code> y <code>rotate()</code> se miden en <strong>radianes</strong>: una vuelta completa es <code>Math.PI * 2</code>.</p>\n\n    <h3>Ejemplo: formas básicas</h3>\n    <div class=\"demo\"><div class=\"lienzo-caja\"><canvas id=\"demo-formas\" width=\"400\" height=\"300\" aria-label=\"Rectángulos, círculo, triángulo y texto dibujados con canvas\"></canvas></div></div>\n    <p class=\"pie-lienzo\">Rectángulo con <code>fillRect</code>, borde con <code>strokeRect</code>, círculo con <code>arc</code>, triángulo con <code>lineTo</code>.</p>\n    </section>\n\n    <section>\n    <h2>Animación</h2>\n    <p>Una animación es dibujar muchas imágenes seguidas. En cada cuadro se borra el canvas con <code>clearRect()</code>, se actualizan\n    las posiciones y se dibuja de nuevo. <code>requestAnimationFrame()</code> le pide al navegador que ejecute tu función justo antes\n    de pintar el siguiente cuadro, normalmente 60 veces por segundo.</p>\n<pre><code>function cuadro() {\n  ctx.clearRect(0, 0, c.width, c.height);  // borrar\n  x += vx;                                  // actualizar\n  ctx.arc(x, y, r, 0, Math.PI * 2);         // dibujar\n  requestAnimationFrame(cuadro);            // repetir\n}\ncuadro();</code></pre>\n    <div class=\"demo\"><div class=\"lienzo-caja\"><canvas id=\"demo-animacion\" width=\"400\" height=\"220\" aria-label=\"Pelota que rebota en los bordes del canvas\"></canvas></div></div>\n    <p class=\"pie-lienzo\">La pelota rebota porque se invierte su velocidad al llegar a un borde.</p>\n    </section>\n\n    <section>\n    <h2>Práctica de clase: texto arcoíris</h2>\n    <p>Dibujar el mismo texto siete veces, cada una con un color distinto y desplazada 3 píxeles, crea el efecto de sombra arcoíris.\n    Usa un ciclo, un arreglo de colores y <code>fillText()</code>.</p>\n    <div class=\"demo\"><div class=\"lienzo-caja\"><canvas id=\"demo-arcoiris\" width=\"500\" height=\"80\" aria-label=\"Texto Hello World con efecto arcoíris\"></canvas></div></div>\n    </section>\n\n    <section>\n    <h2>Del canvas a p5.js</h2>\n    <p>Todo lo anterior funciona, pero requiere mucho código para cosas simples. p5.js envuelve el contexto 2D con funciones más cortas.\n    Lo que aquí es <code>ctx.fillRect(20, 20, 150, 100)</code>, allá es <code>rect(20, 20, 150, 100)</code>.\n    Sigue en <a href=\"p5.html\">la página de p5.js</a>.</p>\n    </section>\n\n\n  </main>\n  <footer>\n    <!-- Aquí va el nombre del alumno -->\n    Práctica de Graficación · Hecho con HTML, CSS, JavaScript y p5.js · Espinosa Perez Jose Hugo\n  </footer>\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/canvas-demos.js\"></script>\n</body>\n</html>\n", "p5.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>p5.js · Graficación</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&family=Literata:ital,wght@0,400;0,600;1,400&display=swap\" />\n  <link rel=\"stylesheet\" href=\"css/styles.css\" />\n  \n</head>\n<body>\n  <header class=\"barra\">\n    <div class=\"barra-interior\">\n      <a class=\"marca\" href=\"index.html\">Graficación</a>\n      <button class=\"boton-menu\" id=\"boton-menu\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n      <nav class=\"menu\" id=\"menu\" aria-label=\"Principal\">\n        <a href=\"index.html\">Inicio</a>\n        <a href=\"canvas.html\">El canvas</a>\n        <a href=\"p5.html\" aria-current=\"page\">p5.js</a>\n        <a href=\"dom.html\">El DOM</a>\n        <a href=\"dom-inspector.html\">Inspector DOM</a>\n        <span class=\"grupo\">Proyectos</span>\n        <a href=\"proyectos/rana.html\">Rana</a>\n        <a href=\"proyectos/dientes.html\">Dientes de conejo</a>\n        <a href=\"proyectos/cena.html\">¿Qué hay de cena?</a>\n        <a href=\"proyectos/nevado.html\">Día nevado soleado</a>\n        <a href=\"proyectos/muneco.html\">Muñeco de nieve</a>\n      </nav>\n    </div>\n  </header>\n  <main>\n    <h1>Fundamentos de p5.js</h1>\n    <p class=\"intro\">p5.js es una librería de JavaScript para dibujar y animar con pocas líneas de código. Es la que se usó para hacer\n    los cinco dibujos de este sitio.</p>\n\n    <section>\n    <h2>Qué es</h2>\n    <p>p5.js es una librería de código abierto pensada para la programación creativa. Está inspirada en Processing, un lenguaje\n    creado para enseñar programación a artistas y diseñadores, y lleva esa misma idea a la web. Por debajo usa el\n    <a href=\"canvas.html\">canvas</a> con contexto 2D (y el contexto WebGL cuando se pide el modo <code>WEBGL</code>), pero oculta\n    los detalles para que dibujar sea directo.</p>\n    </section>\n\n    <section>\n    <h2>Cómo se agrega a una página</h2>\n<pre><code>&lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.9.4/p5.min.js\"&gt;&lt;/script&gt;\n&lt;script src=\"js/sketch.js\"&gt;&lt;/script&gt;</code></pre>\n    <p>El primer script carga la librería y el segundo es tu dibujo. El orden importa: p5.js debe cargarse antes que tu código.</p>\n    </section>\n\n    <section>\n    <h2>La estructura: setup() y draw()</h2>\n    <p>Todo programa de p5.js gira alrededor de dos funciones que la librería llama sola:</p>\n    <ul>\n      <li><code>setup()</code> se ejecuta <strong>una vez</strong> al empezar. Aquí se crea el lienzo con <code>createCanvas(ancho, alto)</code>.</li>\n      <li><code>draw()</code> se ejecuta <strong>una y otra vez</strong>, unas 60 veces por segundo. Aquí van el dibujo y la animación.</li>\n    </ul>\n<pre><code>function setup() {\n  createCanvas(400, 400);\n}\n\nfunction draw() {\n  background(220);\n  fill(255, 0, 0);\n  ellipse(mouseX, mouseY, 50, 50);\n}</code></pre>\n\n    <h3>Demo en vivo</h3>\n    <div class=\"demo\"><div class=\"lienzo-caja\" id=\"demo-p5\"></div></div>\n    <p class=\"pie-lienzo\">Mueve el mouse sobre el lienzo. El tamaño del círculo depende de qué tan rápido lo muevas.</p>\n    </section>\n\n    <section>\n    <h2>Funciones de dibujo</h2>\n    <div class=\"tabla-envoltura\">\n      <table>\n        <thead><tr><th>Tema</th><th>Funciones</th></tr></thead>\n        <tbody>\n          <tr><td>Fondo y lienzo</td><td><code>createCanvas()</code>, <code>background()</code></td></tr>\n          <tr><td>Formas</td><td><code>point()</code>, <code>line()</code>, <code>rect()</code>, <code>ellipse()</code>, <code>circle()</code>, <code>triangle()</code>, <code>arc()</code>, <code>quad()</code>, <code>beginShape()</code></td></tr>\n          <tr><td>Relleno y contorno</td><td><code>fill()</code>, <code>noFill()</code>, <code>stroke()</code>, <code>noStroke()</code>, <code>strokeWeight()</code></td></tr>\n          <tr><td>Texto</td><td><code>text()</code>, <code>textSize()</code>, <code>textAlign()</code></td></tr>\n          <tr><td>Matemáticas</td><td><code>map()</code>, <code>constrain()</code>, <code>lerp()</code>, <code>dist()</code>, <code>random()</code>, <code>sin()</code>, <code>cos()</code></td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p>p5.js dibuja como si pintaras con capas: lo que se dibuja después queda encima. Por eso en el muñeco de nieve el sombrero\n    se dibuja al final. Además, <code>fill()</code> y <code>stroke()</code> se quedan activos hasta que los cambies.</p>\n    </section>\n\n    <section>\n    <h2>Color</h2>\n    <p>Por defecto los colores son RGB (rojo, verde, azul, de 0 a 255). <code>fill(255, 0, 0)</code> es rojo y <code>fill(128)</code> es gris.\n    Con <code>colorMode(HSB)</code> se pueden describir por matiz, saturación y brillo, ideal para hacer cambios de color suaves, como en la demo.\n    <code>lerpColor()</code> calcula un color intermedio entre dos; sirve, por ejemplo, para hacer degradados de cielo.</p>\n    </section>\n\n    <section>\n    <h2>Variables del sistema</h2>\n    <p>p5.js crea variables que siempre están actualizadas:</p>\n    <ul>\n      <li><code>width</code> y <code>height</code>: tamaño del lienzo.</li>\n      <li><code>mouseX</code> y <code>mouseY</code>: posición del mouse; <code>pmouseX</code> y <code>pmouseY</code>: posición en el cuadro anterior.</li>\n      <li><code>mouseIsPressed</code>: <code>true</code> mientras se mantiene un botón del mouse.</li>\n      <li><code>frameCount</code>: cuántos cuadros se han dibujado. Sirve para animar con <code>sin(frameCount * 0.05)</code>.</li>\n      <li><code>key</code>: la última tecla presionada.</li>\n    </ul>\n    </section>\n\n    <section>\n    <h2>Eventos</h2>\n    <p>Además de <code>setup()</code> y <code>draw()</code>, p5.js busca funciones con nombres especiales y las ejecuta cuando ocurre algo:\n    <code>mousePressed()</code>, <code>mouseReleased()</code>, <code>mouseMoved()</code>, <code>keyPressed()</code>.\n    Los dibujos de este sitio no las necesitan, pero son la base de cualquier programa interactivo.</p>\n    </section>\n\n    <section>\n    <h2>Transformaciones</h2>\n    <p><code>translate(x, y)</code> mueve el origen, <code>rotate(ángulo)</code> gira el sistema de coordenadas y <code>scale()</code> lo agranda.\n    Como afectan todo lo que se dibuja después, se encierran entre <code>push()</code> y <code>pop()</code>, que guardan y restauran el estado.\n    Por ejemplo, para girar una oreja sobre su base:</p>\n<pre><code>push();\ntranslate(150, 160);   // mover el origen a la base de la oreja\nrotate(angulo);        // girar\nellipse(0, -75, 62, 175);\npop();                 // volver a como estaba</code></pre>\n    <p>Los ángulos se miden en radianes. Con <code>angleMode(DEGREES)</code> puedes usar grados.</p>\n    </section>\n\n    <section>\n    <h2>Modo global y modo instancia</h2>\n    <p>En <strong>modo global</strong>, el que usamos, las funciones como <code>ellipse()</code> están disponibles directamente.\n    En <strong>modo instancia</strong> todo se guarda dentro de un objeto, lo que evita choques de nombres si hay varios dibujos en la misma página:</p>\n<pre><code>const miDibujo = (p) =&gt; {\n  p.setup = () =&gt; { p.createCanvas(400, 400); };\n  p.draw  = () =&gt; { p.background(220); p.ellipse(p.mouseX, p.mouseY, 50); };\n};\nnew p5(miDibujo, 'contenedor');</code></pre>\n    </section>\n\n    <section>\n    <h2>De Khan Academy a p5.js</h2>\n    <p>Khan Academy usa ProcessingJS, que es muy parecido a p5.js. Para llevar un dibujo al sitio hay que hacer algunos cambios:</p>\n    <div class=\"tabla-envoltura\">\n      <table>\n        <thead><tr><th>En Khan Academy</th><th>En p5.js</th></tr></thead>\n        <tbody>\n          <tr><td>El lienzo ya existe (400 × 400)</td><td>Hay que crearlo en <code>setup()</code> con <code>createCanvas(400, 400)</code></td></tr>\n          <tr><td><code>var draw = function() { ... };</code></td><td><code>function draw() { ... }</code></td></tr>\n          <tr><td><code>var mouseClicked = function() { ... };</code></td><td><code>function mouseClicked() { ... }</code></td></tr>\n          <tr><td><code>println(x)</code></td><td><code>console.log(x)</code> o <code>print(x)</code></td></tr>\n          <tr><td>Dibujo sin animación: todo suelto al inicio</td><td>Ponlo dentro de <code>draw()</code>, o en <code>setup()</code> si solo debe dibujarse una vez</td></tr>\n          <tr><td>Ángulos en grados</td><td>Agrega <code>angleMode(DEGREES)</code> en <code>setup()</code></td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p><code>fill()</code>, <code>rect()</code>, <code>ellipse()</code>, <code>random()</code>, <code>map()</code> y <code>mouseX</code> se escriben igual en ambos.</p>\n    </section>\n\n\n  </main>\n  <footer>\n    <!-- Aquí va el nombre del alumno -->\n    Práctica de Graficación · Hecho con HTML, CSS, JavaScript y p5.js · Espinosa Perez Jose Hugo\n  </footer>\n  <script src=\"js/main.js\"></script>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.9.4/p5.min.js\"></script>\n  <script src=\"js/demo-p5.js\"></script>\n</body>\n</html>\n", "dom.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>El DOM · Graficación</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&family=Literata:ital,wght@0,400;0,600;1,400&display=swap\" />\n  <link rel=\"stylesheet\" href=\"css/styles.css\" />\n  \n</head>\n<body>\n  <header class=\"barra\">\n    <div class=\"barra-interior\">\n      <a class=\"marca\" href=\"index.html\">Graficación</a>\n      <button class=\"boton-menu\" id=\"boton-menu\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n      <nav class=\"menu\" id=\"menu\" aria-label=\"Principal\">\n        <a href=\"index.html\">Inicio</a>\n        <a href=\"canvas.html\">El canvas</a>\n        <a href=\"p5.html\">p5.js</a>\n        <a href=\"dom.html\" aria-current=\"page\">El DOM</a>\n        <a href=\"dom-inspector.html\">Inspector DOM</a>\n        <span class=\"grupo\">Proyectos</span>\n        <a href=\"proyectos/rana.html\">Rana</a>\n        <a href=\"proyectos/dientes.html\">Dientes de conejo</a>\n        <a href=\"proyectos/cena.html\">¿Qué hay de cena?</a>\n        <a href=\"proyectos/nevado.html\">Día nevado soleado</a>\n        <a href=\"proyectos/muneco.html\">Muñeco de nieve</a>\n      </nav>\n    </div>\n  </header>\n  <main>\n    <h1>El DOM: Document Object Model</h1>\n    <p class=\"intro\">El DOM es la forma en que el navegador representa tu página para que JavaScript pueda leerla y modificarla mientras está abierta.</p>\n\n    <section>\n    <h2>Qué es</h2>\n    <p>Cuando el navegador abre un archivo HTML, no lo muestra como texto: lo lee y construye con él un <strong>árbol de objetos</strong>.\n    Cada etiqueta (<code>&lt;body&gt;</code>, <code>&lt;h1&gt;</code>, <code>&lt;canvas&gt;</code>…) se convierte en un objeto al que se le llama <strong>nodo</strong>,\n    y los nodos quedan conectados como en un árbol genealógico: padres, hijos y hermanos. A ese árbol se le llama DOM\n    (<em>Document Object Model</em>, \"modelo de objetos del documento\").</p>\n    <p>Una forma de pensarlo: el HTML es el plano escrito de una casa, y el DOM es la casa ya construida. JavaScript no cambia el plano, cambia la casa:\n    puede pintar una pared, agregar una puerta o quitar una ventana, y el navegador actualiza lo que ves sin recargar la página.</p>\n\n    <h3>Un ejemplo de árbol</h3>\n<pre><code>&lt;body&gt;\n  &lt;h1 id=\"titulo\"&gt;Hola&lt;/h1&gt;\n  &lt;p class=\"texto\"&gt;Un párrafo&lt;/p&gt;\n&lt;/body&gt;</code></pre>\n    <p>Ese HTML se convierte en este árbol:</p>\n<pre><code>document\n└── html\n    ├── head\n    │   └── title\n    └── body\n        ├── h1  (id=\"titulo\")  →  texto: \"Hola\"\n        └── p   (class=\"texto\") →  texto: \"Un párrafo\"</code></pre>\n    <p>El objeto <code>document</code> es la puerta de entrada: desde él se llega a todo lo demás.</p>\n    </section>\n\n    <section>\n    <h2>Tipos de nodos</h2>\n    <div class=\"tabla-envoltura\">\n      <table>\n        <thead><tr><th>Nodo</th><th>Qué representa</th></tr></thead>\n        <tbody>\n          <tr><td>Elemento</td><td>Una etiqueta HTML, como <code>&lt;p&gt;</code> o <code>&lt;canvas&gt;</code>.</td></tr>\n          <tr><td>Texto</td><td>El texto que está dentro de un elemento.</td></tr>\n          <tr><td>Atributo</td><td>Los datos de una etiqueta, como <code>id</code>, <code>class</code>, <code>src</code> o <code>width</code>.</td></tr>\n          <tr><td>Comentario</td><td>Los comentarios <code>&lt;!-- --&gt;</code> del HTML.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    </section>\n\n    <section>\n    <h2>Seleccionar elementos</h2>\n    <p>Antes de cambiar algo hay que encontrarlo en el árbol:</p>\n    <div class=\"tabla-envoltura\">\n      <table>\n        <thead><tr><th>Método</th><th>Qué devuelve</th></tr></thead>\n        <tbody>\n          <tr><td><code>document.getElementById('titulo')</code></td><td>El elemento con ese <code>id</code>.</td></tr>\n          <tr><td><code>document.querySelector('.texto')</code></td><td>El primer elemento que coincide con un selector de CSS.</td></tr>\n          <tr><td><code>document.querySelectorAll('p')</code></td><td>Todos los elementos que coinciden, en una lista.</td></tr>\n          <tr><td><code>document.getElementsByClassName('texto')</code></td><td>Todos los elementos con esa clase.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p>En tu práctica de clase ya usaste el DOM sin darte cuenta: <code>document.getElementById(\"myCanvas\")</code> busca en el árbol la etiqueta\n    <code>&lt;canvas&gt;</code> para poder dibujar en ella.</p>\n    </section>\n\n    <section>\n    <h2>Modificar elementos</h2>\n    <div class=\"tabla-envoltura\">\n      <table>\n        <thead><tr><th>Propiedad o método</th><th>Para qué sirve</th></tr></thead>\n        <tbody>\n          <tr><td><code>elemento.textContent = 'Nuevo texto'</code></td><td>Cambiar el texto de un elemento. Es la opción más segura.</td></tr>\n          <tr><td><code>elemento.innerHTML = '&lt;b&gt;Hola&lt;/b&gt;'</code></td><td>Cambiar el contenido, interpretando etiquetas HTML. Se debe evitar con texto escrito por usuarios.</td></tr>\n          <tr><td><code>elemento.style.color = 'red'</code></td><td>Cambiar estilos CSS directamente.</td></tr>\n          <tr><td><code>elemento.classList.add('clase')</code>, <code>.remove()</code>, <code>.toggle()</code></td><td>Agregar, quitar o alternar clases de CSS.</td></tr>\n          <tr><td><code>elemento.setAttribute('width', 400)</code></td><td>Cambiar un atributo.</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <h3>Demo: modificar un elemento</h3>\n    <div class=\"panel-demo\">\n      <h3 id=\"dom-titulo\">Soy un título del DOM</h3>\n      <div class=\"acciones\">\n        <button class=\"boton\" id=\"dom-btn-texto\">Cambiar texto</button>\n        <button class=\"boton\" id=\"dom-btn-color\">Cambiar color</button>\n        <button class=\"boton\" id=\"dom-btn-resaltar\">Resaltar</button>\n      </div>\n    </div>\n<pre><code>titulo.textContent = 'Nuevo texto';          // texto\ntitulo.style.color = 'hsl(200, 70%, 40%)';   // estilo\ntitulo.classList.toggle('resaltado');        // clase de CSS</code></pre>\n    </section>\n\n    <section>\n    <h2>Crear y eliminar elementos</h2>\n    <p>El DOM no solo cambia lo que ya existe: también se pueden crear elementos nuevos desde JavaScript y agregarlos al árbol.</p>\n<pre><code>const item = document.createElement('li');   // 1. crear\nitem.textContent = 'Nuevo elemento';         // 2. darle contenido\nlista.append(item);                          // 3. agregarlo al árbol\nitem.remove();                               // quitarlo</code></pre>\n\n    <h3>Demo: crear y quitar elementos</h3>\n    <div class=\"panel-demo\">\n      <label for=\"dom-nueva\">Nuevo elemento:</label>\n      <input id=\"dom-nueva\" type=\"text\" placeholder=\"Escribe algo\" />\n      <button class=\"boton\" id=\"dom-btn-agregar\">Agregar</button>\n      <ul id=\"dom-lista\"></ul>\n      <p class=\"pie-lienzo\">Haz clic en un elemento de la lista para quitarlo.</p>\n    </div>\n    </section>\n\n    <section>\n    <h2>Eventos</h2>\n    <p>Un evento es algo que ocurre en la página: un clic, mover el mouse, escribir en un campo. Con\n    <code>addEventListener</code> le dices al navegador qué función ejecutar cuando pase:</p>\n<pre><code>boton.addEventListener('click', () =&gt; {\n  titulo.textContent = '¡Hiciste clic!';\n});</code></pre>\n    <p>Los eventos más usados son <code>click</code>, <code>pointermove</code> (mover el mouse o el dedo), <code>keydown</code> (tecla presionada) e <code>input</code> (cambio en un campo de texto).</p>\n\n    <h3>Demo: reaccionar mientras escribes</h3>\n    <div class=\"panel-demo\">\n      <label for=\"dom-entrada\">Escribe tu nombre:</label>\n      <input id=\"dom-entrada\" type=\"text\" placeholder=\"Tu nombre\" />\n      <p id=\"dom-eco\">Hola, desconocido.</p>\n    </div>\n    </section>\n\n    <section>\n    <h2>El DOM y el canvas</h2>\n    <p>El elemento <code>&lt;canvas&gt;</code> es parte del DOM: es un nodo más del árbol, y se puede seleccionar, cambiar de tamaño o acomodar con CSS.\n    Pero <strong>lo que dibujas dentro del canvas no está en el DOM</strong>. Son solo píxeles. La rana o el muñeco de nieve no son elementos que puedas\n    seleccionar con <code>getElementById</code>; el navegador solo ve un rectángulo con una imagen adentro.</p>\n    <div class=\"nota\"><p>Por eso un botón o un menú se hacen con elementos del DOM, y los dibujos animados con canvas. Muchas páginas combinan los dos.</p></div>\n    </section>\n\n    <section>\n    <h2>El DOM y p5.js</h2>\n    <p>p5.js trabaja con el DOM de dos formas. La primera: el lienzo que crea con <code>createCanvas()</code> es un <code>&lt;canvas&gt;</code> normal, y\n    <code>.parent('id')</code> lo coloca dentro de un elemento de la página. Así se colocan los dibujos de este sitio dentro de <code>&lt;div id=\"lienzo\"&gt;</code>.</p>\n    <p>La segunda: p5.js puede crear controles del DOM, como botones, deslizadores y campos de texto, con <code>createButton()</code>, <code>createSlider()</code> y <code>createInput()</code>.</p>\n<pre><code>deslizador = createSlider(10, 150, 60);   // mínimo, máximo, valor inicial\nboton = createButton('Cambiar color');\nboton.mousePressed(() =&gt; { /* ... */ });\n// y en draw(): deslizador.value()</code></pre>\n\n    <h3>Demo: controles del DOM con p5.js</h3>\n    <div class=\"panel-demo\">\n      <div id=\"dom-p5-controles\" class=\"acciones\"></div>\n      <div class=\"lienzo-caja\" id=\"dom-p5\"></div>\n    </div>\n    </section>\n\n    <section>\n    <h2>Dónde se usa el DOM en este sitio</h2>\n    <ul>\n      <li><strong>El menú del celular:</strong> el botón \"Menú\" agrega o quita la clase <code>abierto</code> con <code>classList.toggle()</code>.</li>\n      <li><strong>El botón \"Ver código\":</strong> carga el archivo del dibujo, escribe su texto con <code>textContent</code> y muestra u oculta el bloque con el atributo <code>hidden</code>.</li>\n      <li><strong>El plano de la portada:</strong> busca su canvas con <code>getElementById</code> y escucha el evento <code>pointermove</code>.</li>\n      <li><strong>Los dibujos con p5.js:</strong> usan <code>.parent('lienzo')</code> para colocar el canvas dentro de la página.</li>\n    </ul>\n    <p>Para ver el árbol del DOM de cada página de este sitio, dibujado con cajas y líneas, abre el <a href=\"dom-inspector.html\">Inspector del DOM</a>.</p>\n    </section>\n\n\n  </main>\n  <footer>\n    <!-- Aquí va el nombre del alumno -->\n    Práctica de Graficación · Hecho con HTML, CSS, JavaScript y p5.js · Espinosa Perez Jose Hugo\n  </footer>\n  <script src=\"js/main.js\"></script>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.9.4/p5.min.js\"></script>\n  <script src=\"js/dom-demos.js\"></script>\n  <script src=\"js/demo-dom-p5.js\"></script>\n</body>\n</html>\n", "dom-inspector.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Inspector DOM · Graficación</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&family=Literata:ital,wght@0,400;0,600;1,400&display=swap\" />\n  <link rel=\"stylesheet\" href=\"css/styles.css\" />\n  \n</head>\n<body>\n  <header class=\"barra\">\n    <div class=\"barra-interior\">\n      <a class=\"marca\" href=\"index.html\">Graficación</a>\n      <button class=\"boton-menu\" id=\"boton-menu\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n      <nav class=\"menu\" id=\"menu\" aria-label=\"Principal\">\n        <a href=\"index.html\">Inicio</a>\n        <a href=\"canvas.html\">El canvas</a>\n        <a href=\"p5.html\">p5.js</a>\n        <a href=\"dom.html\">El DOM</a>\n        <a href=\"dom-inspector.html\" aria-current=\"page\">Inspector DOM</a>\n        <span class=\"grupo\">Proyectos</span>\n        <a href=\"proyectos/rana.html\">Rana</a>\n        <a href=\"proyectos/dientes.html\">Dientes de conejo</a>\n        <a href=\"proyectos/cena.html\">¿Qué hay de cena?</a>\n        <a href=\"proyectos/nevado.html\">Día nevado soleado</a>\n        <a href=\"proyectos/muneco.html\">Muñeco de nieve</a>\n      </nav>\n    </div>\n  </header>\n  <main>\n    <h1>Inspector del DOM</h1>\n    <p class=\"intro\">Cada página de este sitio es un árbol: <code>&lt;html&gt;</code> es la raíz, de ella salen <code>&lt;head&gt;</code> y\n    <code>&lt;body&gt;</code>, y dentro del cuerpo hay contenedores como <code>&lt;header&gt;</code>, <code>&lt;main&gt;</code> y\n    <code>&lt;footer&gt;</code> con sus hijos (<code>&lt;h1&gt;</code>, <code>&lt;p&gt;</code>, <code>&lt;canvas&gt;</code>…).\n    Aquí puedes ver ese árbol dibujado, página por página. Si quieres la teoría, está en <a href=\"dom.html\">El DOM</a>.</p>\n\n    <section>\n      <h2>Elige una página</h2>\n      <div class=\"paginas\" id=\"selector-paginas\" role=\"group\" aria-label=\"Páginas del sitio\"></div>\n      <noscript><p>Esta página necesita JavaScript para dibujar el árbol.</p></noscript>\n    </section>\n\n    <section>\n      <h2>Árbol del DOM</h2>\n      <p class=\"estado-inspector\" id=\"inspector-estado\" aria-live=\"polite\"></p>\n      <div class=\"herramientas\">\n        <button class=\"boton\" type=\"button\" id=\"btn-expandir\">Expandir todo</button>\n        <button class=\"boton\" type=\"button\" id=\"btn-inicial\">Vista inicial</button>\n        <button class=\"boton\" type=\"button\" id=\"btn-contraer\">Contraer todo</button>\n      </div>\n      <div class=\"inspector-panel\">\n        <div class=\"arbol-scroll\" id=\"arbol-scroll\">\n          <div class=\"arbol\" id=\"arbol\"></div>\n        </div>\n      </div>\n      <div class=\"detalle\" id=\"detalle\" aria-live=\"polite\"></div>\n    </section>\n\n    <section>\n      <h2>Cómo leer el árbol</h2>\n      <ul class=\"leyenda\">\n        <li><span class=\"muestra\"></span> Etiqueta escrita en el HTML</li>\n        <li><span class=\"muestra discontinua\"></span> Elemento que crea JavaScript al ejecutarse (el <code>&lt;canvas&gt;</code> de p5.js)</li>\n        <li><span class=\"muestra activa\"></span> Etiqueta seleccionada</li>\n      </ul>\n      <ul>\n        <li>Haz clic en una caja para <strong>abrir o cerrar</strong> sus hijos. El número junto a la flecha ▸ indica cuántos hijos tiene.</li>\n        <li>El texto gris debajo de la etiqueta es su <code>id</code> (<code>#</code>) o su primera clase (<code>.</code>).</li>\n        <li><code>&lt;link&gt; ×4</code> significa que hay 4 etiquetas iguales seguidas, que se agrupan para que el árbol no se vuelva enorme.</li>\n        <li>Abajo del árbol aparecen los datos de la caja seleccionada: su ruta, sus atributos y su texto.</li>\n        <li>Las páginas de los dibujos muestran el contenedor <code>#lienzo</code> con un <code>&lt;canvas&gt;</code> discontinuo: p5.js lo agrega al ejecutar el programa.</li>\n      </ul>\n    </section>\n\n  </main>\n  <footer>\n    <!-- Aquí va el nombre del alumno -->\n    Práctica de Graficación · Hecho con HTML, CSS, JavaScript y p5.js · Espinosa Perez Jose Hugo\n  </footer>\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/paginas-data.js\"></script>\n  <script src=\"js/dom-inspector.js\"></script>\n</body>\n</html>\n", "proyectos/rana.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Rana · Graficación</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&family=Literata:ital,wght@0,400;0,600;1,400&display=swap\" />\n  <link rel=\"stylesheet\" href=\"../css/styles.css\" />\n  \n</head>\n<body>\n  <header class=\"barra\">\n    <div class=\"barra-interior\">\n      <a class=\"marca\" href=\"../index.html\">Graficación</a>\n      <button class=\"boton-menu\" id=\"boton-menu\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n      <nav class=\"menu\" id=\"menu\" aria-label=\"Principal\">\n        <a href=\"../index.html\">Inicio</a>\n        <a href=\"../canvas.html\">El canvas</a>\n        <a href=\"../p5.html\">p5.js</a>\n        <a href=\"../dom.html\">El DOM</a>\n        <a href=\"../dom-inspector.html\">Inspector DOM</a>\n        <span class=\"grupo\">Proyectos</span>\n        <a href=\"../proyectos/rana.html\" aria-current=\"page\">Rana</a>\n        <a href=\"../proyectos/dientes.html\">Dientes de conejo</a>\n        <a href=\"../proyectos/cena.html\">¿Qué hay de cena?</a>\n        <a href=\"../proyectos/nevado.html\">Día nevado soleado</a>\n        <a href=\"../proyectos/muneco.html\">Muñeco de nieve</a>\n      </nav>\n    </div>\n  </header>\n  <main>\n    <h1>Rana</h1>\n    <p class=\"intro\">Una rana verde con ojos saltones, hecha solo con círculos y cuadrados.</p>\n\n    <div class=\"proyecto\">\n      <div>\n        <div class=\"lienzo-caja\" id=\"lienzo\"></div>\n      </div>\n      <div>\n        <h2>Qué muestra</h2>\n        <ul>\n        <li>Es un dibujo estático: la rana está colocada en x = 250 y y = 150.</li>\n        <li>Si cambias esos dos números en el código, toda la rana se mueve junta.</li>\n        </ul>\n        <h2>Qué conceptos usa</h2>\n        <ul>\n        <li>Variables (<code>x</code> y <code>y</code>) para colocar todas las partes respecto a un mismo punto</li>\n        <li><code>ellipse()</code> para la cara, las cuencas de los ojos, los ojos y la boca</li>\n        <li><code>noStroke()</code> para quitar los bordes y <code>fill()</code> con valores RGB</li>\n        <li>El orden de las capas: lo que se dibuja después queda encima</li>\n        <li><code>rect()</code> para las pupilas cuadradas</li>\n        </ul>\n        <button class=\"boton\" id=\"ver-codigo\" data-archivo=\"../js/rana.js\">Ver código</button>\n      </div>\n    </div>\n\n    <pre id=\"bloque-codigo\" hidden><code></code></pre>\n\n    <div class=\"navegacion-proyectos\">\n      <span></span>\n      <a href=\"dientes.html\">Dientes de conejo →</a>\n    </div>\n\n  </main>\n  <footer>\n    <!-- Aquí va el nombre del alumno -->\n    Práctica de Graficación · Hecho con HTML, CSS, JavaScript y p5.js · Espinosa Perez Jose Hugo\n  </footer>\n  <script src=\"../js/main.js\"></script>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.9.4/p5.min.js\"></script>\n  <script src=\"../js/rana.js\"></script>\n</body>\n</html>\n", "proyectos/dientes.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Dientes de conejo · Graficación</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&family=Literata:ital,wght@0,400;0,600;1,400&display=swap\" />\n  <link rel=\"stylesheet\" href=\"../css/styles.css\" />\n  \n</head>\n<body>\n  <header class=\"barra\">\n    <div class=\"barra-interior\">\n      <a class=\"marca\" href=\"../index.html\">Graficación</a>\n      <button class=\"boton-menu\" id=\"boton-menu\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n      <nav class=\"menu\" id=\"menu\" aria-label=\"Principal\">\n        <a href=\"../index.html\">Inicio</a>\n        <a href=\"../canvas.html\">El canvas</a>\n        <a href=\"../p5.html\">p5.js</a>\n        <a href=\"../dom.html\">El DOM</a>\n        <a href=\"../dom-inspector.html\">Inspector DOM</a>\n        <span class=\"grupo\">Proyectos</span>\n        <a href=\"../proyectos/rana.html\">Rana</a>\n        <a href=\"../proyectos/dientes.html\" aria-current=\"page\">Dientes de conejo</a>\n        <a href=\"../proyectos/cena.html\">¿Qué hay de cena?</a>\n        <a href=\"../proyectos/nevado.html\">Día nevado soleado</a>\n        <a href=\"../proyectos/muneco.html\">Muñeco de nieve</a>\n      </nav>\n    </div>\n  </header>\n  <main>\n    <h1>Dientes de conejo</h1>\n    <p class=\"intro\">Un conejo con orejas rosas, mejillas, bigotes y dos dientes grandes.</p>\n\n    <div class=\"proyecto\">\n      <div>\n        <div class=\"lienzo-caja\" id=\"lienzo\"></div>\n      </div>\n      <div>\n        <h2>Qué muestra</h2>\n        <ul>\n        <li>Es un dibujo estático.</li>\n        <li>Cambia <code>eyeSize</code> o <code>toothLength</code> en el código para ver ojos y dientes de otro tamaño.</li>\n        </ul>\n        <h2>Qué conceptos usa</h2>\n        <ul>\n        <li>Variables (<code>eyeSize</code> y <code>toothLength</code>) para controlar el tamaño de las partes</li>\n        <li><code>ellipse()</code> para orejas, cara y ojos</li>\n        <li><code>line()</code> para la boca y los bigotes, y <code>rect()</code> para los dientes</li>\n        <li><code>fill()</code>, <code>stroke()</code>, <code>noStroke()</code> y <code>strokeWeight()</code> para cambiar colores y bordes entre figuras</li>\n        </ul>\n        <button class=\"boton\" id=\"ver-codigo\" data-archivo=\"../js/dientes.js\">Ver código</button>\n      </div>\n    </div>\n\n    <pre id=\"bloque-codigo\" hidden><code></code></pre>\n\n    <div class=\"navegacion-proyectos\">\n      <a href=\"rana.html\">← Rana</a>\n      <a href=\"cena.html\">¿Qué hay de cena? →</a>\n    </div>\n\n  </main>\n  <footer>\n    <!-- Aquí va el nombre del alumno -->\n    Práctica de Graficación · Hecho con HTML, CSS, JavaScript y p5.js · Espinosa Perez Jose Hugo\n  </footer>\n  <script src=\"../js/main.js\"></script>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.9.4/p5.min.js\"></script>\n  <script src=\"../js/dientes.js\"></script>\n</body>\n</html>\n", "proyectos/cena.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>¿Qué hay de cena? · Graficación</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&family=Literata:ital,wght@0,400;0,600;1,400&display=swap\" />\n  <link rel=\"stylesheet\" href=\"../css/styles.css\" />\n  \n</head>\n<body>\n  <header class=\"barra\">\n    <div class=\"barra-interior\">\n      <a class=\"marca\" href=\"../index.html\">Graficación</a>\n      <button class=\"boton-menu\" id=\"boton-menu\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n      <nav class=\"menu\" id=\"menu\" aria-label=\"Principal\">\n        <a href=\"../index.html\">Inicio</a>\n        <a href=\"../canvas.html\">El canvas</a>\n        <a href=\"../p5.html\">p5.js</a>\n        <a href=\"../dom.html\">El DOM</a>\n        <a href=\"../dom-inspector.html\">Inspector DOM</a>\n        <span class=\"grupo\">Proyectos</span>\n        <a href=\"../proyectos/rana.html\">Rana</a>\n        <a href=\"../proyectos/dientes.html\">Dientes de conejo</a>\n        <a href=\"../proyectos/cena.html\" aria-current=\"page\">¿Qué hay de cena?</a>\n        <a href=\"../proyectos/nevado.html\">Día nevado soleado</a>\n        <a href=\"../proyectos/muneco.html\">Muñeco de nieve</a>\n      </nav>\n    </div>\n  </header>\n  <main>\n    <h1>¿Qué hay de cena?</h1>\n    <p class=\"intro\">Un plato servido en una mesa de madera: bistec, puré de papa, brócoli, zanahorias y cubiertos.</p>\n\n    <div class=\"proyecto\">\n      <div>\n        <div class=\"lienzo-caja\" id=\"lienzo\"></div>\n      </div>\n      <div>\n        <h2>Qué muestra</h2>\n        <ul>\n        <li>Es un dibujo estático.</li>\n        <li>Mira el orden en que se dibujan las partes: primero la mesa y el plato, luego la comida y al final los cubiertos.</li>\n        </ul>\n        <h2>Qué conceptos usa</h2>\n        <ul>\n        <li><code>background()</code> para pintar la mesa</li>\n        <li>Varios <code>ellipse()</code> encimados para hacer el plato, el puré y el brócoli</li>\n        <li><code>stroke()</code>, <code>noStroke()</code> y <code>strokeWeight()</code> para controlar los bordes</li>\n        <li><code>line()</code> para los detalles del bistec y los cubiertos</li>\n        </ul>\n        <button class=\"boton\" id=\"ver-codigo\" data-archivo=\"../js/cena.js\">Ver código</button>\n      </div>\n    </div>\n\n    <pre id=\"bloque-codigo\" hidden><code></code></pre>\n\n    <div class=\"navegacion-proyectos\">\n      <a href=\"dientes.html\">← Dientes de conejo</a>\n      <a href=\"nevado.html\">Día nevado soleado →</a>\n    </div>\n\n  </main>\n  <footer>\n    <!-- Aquí va el nombre del alumno -->\n    Práctica de Graficación · Hecho con HTML, CSS, JavaScript y p5.js · Espinosa Perez Jose Hugo\n  </footer>\n  <script src=\"../js/main.js\"></script>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.9.4/p5.min.js\"></script>\n  <script src=\"../js/cena.js\"></script>\n</body>\n</html>\n", "proyectos/nevado.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Día nevado soleado · Graficación</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&family=Literata:ital,wght@0,400;0,600;1,400&display=swap\" />\n  <link rel=\"stylesheet\" href=\"../css/styles.css\" />\n  \n</head>\n<body>\n  <header class=\"barra\">\n    <div class=\"barra-interior\">\n      <a class=\"marca\" href=\"../index.html\">Graficación</a>\n      <button class=\"boton-menu\" id=\"boton-menu\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n      <nav class=\"menu\" id=\"menu\" aria-label=\"Principal\">\n        <a href=\"../index.html\">Inicio</a>\n        <a href=\"../canvas.html\">El canvas</a>\n        <a href=\"../p5.html\">p5.js</a>\n        <a href=\"../dom.html\">El DOM</a>\n        <a href=\"../dom-inspector.html\">Inspector DOM</a>\n        <span class=\"grupo\">Proyectos</span>\n        <a href=\"../proyectos/rana.html\">Rana</a>\n        <a href=\"../proyectos/dientes.html\">Dientes de conejo</a>\n        <a href=\"../proyectos/cena.html\">¿Qué hay de cena?</a>\n        <a href=\"../proyectos/nevado.html\" aria-current=\"page\">Día nevado soleado</a>\n        <a href=\"../proyectos/muneco.html\">Muñeco de nieve</a>\n      </nav>\n    </div>\n  </header>\n  <main>\n    <h1>Día nevado soleado</h1>\n    <p class=\"intro\">Un muñeco de nieve bajo el sol, con nieve que cae sin parar.</p>\n\n    <div class=\"proyecto\">\n      <div>\n        <div class=\"lienzo-caja\" id=\"lienzo\"></div>\n      </div>\n      <div>\n        <h2>Qué muestra</h2>\n        <ul>\n        <li>La nieve cae sola. Cuando un copo llega al fondo, vuelve a aparecer arriba.</li>\n        <li>El dibujo base es el de Khan Academy, con los colores arreglados.</li>\n        </ul>\n        <h2>Qué conceptos usa</h2>\n        <ul>\n        <li>Un arreglo de objetos (<code>copos</code>) con posición, tamaño y velocidad de cada copo</li>\n        <li>Un ciclo <code>for</code> dentro de <code>draw()</code> para dibujar y mover todos los copos</li>\n        <li><code>random()</code> para que cada copo sea distinto</li>\n        <li>Animación: <code>draw()</code> se repite y cambia la posición de los copos en cada cuadro</li>\n        </ul>\n        <button class=\"boton\" id=\"ver-codigo\" data-archivo=\"../js/nevado.js\">Ver código</button>\n      </div>\n    </div>\n\n    <pre id=\"bloque-codigo\" hidden><code></code></pre>\n\n    <div class=\"navegacion-proyectos\">\n      <a href=\"cena.html\">← ¿Qué hay de cena?</a>\n      <a href=\"muneco.html\">Muñeco de nieve →</a>\n    </div>\n\n  </main>\n  <footer>\n    <!-- Aquí va el nombre del alumno -->\n    Práctica de Graficación · Hecho con HTML, CSS, JavaScript y p5.js · Espinosa Perez Jose Hugo\n  </footer>\n  <script src=\"../js/main.js\"></script>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.9.4/p5.min.js\"></script>\n  <script src=\"../js/nevado.js\"></script>\n</body>\n</html>\n", "proyectos/muneco.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Muñeco de nieve · Graficación</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&family=Literata:ital,wght@0,400;0,600;1,400&display=swap\" />\n  <link rel=\"stylesheet\" href=\"../css/styles.css\" />\n  \n</head>\n<body>\n  <header class=\"barra\">\n    <div class=\"barra-interior\">\n      <a class=\"marca\" href=\"../index.html\">Graficación</a>\n      <button class=\"boton-menu\" id=\"boton-menu\" aria-expanded=\"false\" aria-controls=\"menu\">Menú</button>\n      <nav class=\"menu\" id=\"menu\" aria-label=\"Principal\">\n        <a href=\"../index.html\">Inicio</a>\n        <a href=\"../canvas.html\">El canvas</a>\n        <a href=\"../p5.html\">p5.js</a>\n        <a href=\"../dom.html\">El DOM</a>\n        <a href=\"../dom-inspector.html\">Inspector DOM</a>\n        <span class=\"grupo\">Proyectos</span>\n        <a href=\"../proyectos/rana.html\">Rana</a>\n        <a href=\"../proyectos/dientes.html\">Dientes de conejo</a>\n        <a href=\"../proyectos/cena.html\">¿Qué hay de cena?</a>\n        <a href=\"../proyectos/nevado.html\">Día nevado soleado</a>\n        <a href=\"../proyectos/muneco.html\" aria-current=\"page\">Muñeco de nieve</a>\n      </nav>\n    </div>\n  </header>\n  <main>\n    <h1>Muñeco de nieve</h1>\n    <p class=\"intro\">Un muñeco con sombrero, bufanda, nariz de zanahoria, ojos y boca de carbón.</p>\n\n    <div class=\"proyecto\">\n      <div>\n        <div class=\"lienzo-caja\" id=\"lienzo\"></div>\n      </div>\n      <div>\n        <h2>Qué muestra</h2>\n        <ul>\n        <li>Es un dibujo estático.</li>\n        <li>El cuerpo es el del programa original; se le agregaron la cara, la bufanda y el sombrero.</li>\n        </ul>\n        <h2>Qué conceptos usa</h2>\n        <ul>\n        <li>El orden de las capas: los brazos se dibujan antes que el cuerpo para que salgan de atrás</li>\n        <li><code>triangle()</code> para la nariz y <code>line()</code> con <code>strokeWeight()</code> para los brazos</li>\n        <li>Tres <code>ellipse()</code> superpuestos para el cuerpo</li>\n        <li><code>stroke()</code> y <code>noStroke()</code> para cambiar entre bordes y figuras sin borde</li>\n        </ul>\n        <button class=\"boton\" id=\"ver-codigo\" data-archivo=\"../js/muneco.js\">Ver código</button>\n      </div>\n    </div>\n\n    <pre id=\"bloque-codigo\" hidden><code></code></pre>\n\n    <div class=\"navegacion-proyectos\">\n      <a href=\"nevado.html\">← Día nevado soleado</a>\n      <span></span>\n    </div>\n\n  </main>\n  <footer>\n    <!-- Aquí va el nombre del alumno -->\n    Práctica de Graficación · Hecho con HTML, CSS, JavaScript y p5.js · Espinosa Perez Jose Hugo\n  </footer>\n  <script src=\"../js/main.js\"></script>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.9.4/p5.min.js\"></script>\n  <script src=\"../js/muneco.js\"></script>\n</body>\n</html>\n"};
